// SHA-256 c35423fd88f1abcceb426e12abfbbb5ab10e9c5ee193c39c232c2be4107f886d
// All other bodies retain the original frozen e339/a45 bytes. The independent
// decoded tee oracle is applied only after selecting these pre-tee expectations.
pub fn pre_tee_body(profile: &str, index: usize) -> Option<Vec<u8>> {
    let hex = match (profile, index) {
        (_, 0) => "04017f017e017f027f2300210320034100490440000b200341006b220441808002490440000b200424004180082100200021022002200324000f0b",
        (_, 1) => "06017f017e017f017e017f027f2300210520054100490440000b200541006b220641808002490440000b2006240041800821004208210120002001a76a2102200221042004200524000f0b",
        ("plain", 7) => "",
        ("basic", 7) => "",
        ("basic", 10) => "",
        _ => return None,
    };
    Some((0..hex.len()).step_by(2)
        .map(|n| u8::from_str_radix(&hex[n..n + 2], 16).unwrap()).collect())
}
